 function dropLoot(e){const gear=['SINGULARITY CORE','PHASE WEAVE','ECHO MAG'];const item=e.elite?gear[Math.floor(Math.random()*gear.length)]:['CHRONO CELL','FIELD MEDKIT'][Math.floor(Math.random()*2)];loot.push({x:e.x,y:e.y,item,life:18});toast('LOOT DETECTED — '+item)}

