--- index.html
+++ index.html
@@ -51,9 +51,9 @@
 function reload(){if(player.ammo===12||player.reserve===0||reloadTimer>0)return;reloadTimer=1.05;toast('RELOADING')}
 function useLoot(){for(let i=loot.length-1;i>=0;i--){let l=loot[i];if(Math.hypot(l.x-player.x,l.y-player.y)<1.15){if(l.item==='SINGULARITY CORE'){player.gear='SINGULARITY';player.ammo=12;player.hp=Math.min(100,player.hp+15);toast('SINGULARITY CORE — DAMAGE +40%')}else if(l.item==='PHASE WEAVE'){player.gear='PHASE';player.hp=100;player.charge=100;toast('PHASE WEAVE — FULL RECOVERY')}else if(l.item==='ECHO MAG'){player.reserve+=36;player.ammo=12;toast('ECHO MAG — AMMO REPLICATED')}else if(l.item==='CHRONO CELL'){player.charge=Math.min(100,player.charge+45);toast('CHRONO CELL — CHARGE RESTORED')}else{player.hp=Math.min(100,player.hp+35);toast('FIELD MEDKIT — VITALS RESTORED')}loot.splice(i,1);updateHUD();return}}}
 function nextStep(){running=false;if(stage===0){showChoice('The relay is still alive.','A voice cuts through the static — Dr. Sato is trapped inside the relay station. The Array core is destabilizing. You have time for one.',[{title:'Save Dr. Sato',desc:'Trust the scientist. Unlocks a powerful ally — but the Array keeps counting.',id:'sato'},{title:'Secure the core',desc:'Take control of the Array. Gain a permanent chrono boost — leave Sato behind.',id:'core'}]);return}if(stage===1){showChoice('The Array has one cycle left.','You reach the control chamber. The fracture can be sealed — or redirected. There is no clean answer.',[{title:'Seal the breach',desc:'End the invasion. The timeline survives, but the world forgets you.',id:'seal'},{title:'Rewrite the hour',desc:'Undo the first rupture. Restore what was lost — at a cost you cannot predict.',id:'rewrite'}]);return}finish()}
 function showChoice(title,text,opts){paused=true;document.exitPointerLock?.();document.getElementById('choiceTitle').textContent=title;document.getElementById('choiceText').textContent=text;const box=document.getElementById('choices');box.innerHTML='';opts.forEach(o=>{const b=document.createElement('button');b.className='choice';b.innerHTML='<small>DECISION 0'+(stage+1)+'</small><b>'+o.title+'</b><span>'+o.desc+'</span>';b.onclick=()=>makeChoice(o.id);box.appendChild(b)});document.getElementById('choicePanel').classList.remove('hidden')}
-function makeChoice(id){choiceMade=id;if(id==='core'){player.charge=100;player.gear='SINGULARITY';toast('ARRAY CORE SECURED — CHRONO CAPACITY MAXED')}if(id==='sato'){player.hp=100;player.reserve+=24}if(id==='rewrite')player.gear='PHASE';stage++;player.x=2.5;player.y=2.5;player.a=0;spawnStage();document.getElementById('choicePanel').classList.add('hidden');running=true;paused=false;last=performance.now();updateHUD();canvas.requestPointerLock?.();requestAnimationFrame(loop)}
+function makeChoice(id){choiceMade=id;decisions.push(id);if(id==='core'){player.charge=100;player.gear='SINGULARITY';toast('ARRAY CORE SECURED — CHRONO CAPACITY MAXED')}if(id==='sato'){player.hp=100;player.reserve+=24}if(id==='rewrite')player.gear='PHASE';stage++;player.x=2.5;player.y=2.5;player.a=0;spawnStage();document.getElementById('choicePanel').classList.add('hidden');running=true;paused=false;last=performance.now();updateHUD();canvas.requestPointerLock?.();requestAnimationFrame(loop)}
 function finish(){paused=true;document.exitPointerLock?.();let title,text;if(choiceMade==='sato'||choiceMade==='seal'){title='THE QUIET DAWN';text='Dr. Sato used the final seconds to stitch reality shut. The breach is gone. One life remembers the old world — and the choice that made it possible.'}else if(choiceMade==='rewrite'){title='ANOTHER FIRST HOUR';text='The Meridian turns backward. The city wakes without its scars. Somewhere in the new timeline, a stranger dreams of a fight that has not happened yet.'}else{title='THE NEW MERIDIAN';text='You claimed the Array and bent the fracture to your will. The Rift fell silent. The hour belongs to you now — and the timeline will never be safe again.'}document.getElementById('endingTitle').textContent=title;document.getElementById('endingText').textContent=text+'  Kills: '+kills+'  |  Shots fired: '+shots+'  |  Timeline: '+choiceMade.toUpperCase();document.getElementById('endPanel').classList.remove('hidden')}
 function cast(angle){let sin=Math.sin(angle),cos=Math.cos(angle),dist=0,hitX=0,hitY=0;while(dist<20){dist+=.035;hitX=player.x+cos*dist;hitY=player.y+sin*dist;if(cell(hitX,hitY))break}return {dist:dist*Math.cos(angle-player.a),x:hitX,y:hitY,side:(Math.floor(hitX*8)+Math.floor(hitY*8))%2}}
 function render(){const horizon=H*.49+Math.sin(walkBob)*2;const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#09171d');sky.addColorStop(1,'#243538');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);const floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#202a29');floor.addColorStop(1,'#080e10');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
  // horizon haze / distant architecture

